"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4164],{44164:e=>{e.exports=JSON.parse('{"slug":"vvp-kitaya-3-kvartal-2026-eksport","locale":"zh","title":"出口推动中国增速回升至4.5%，零售却仅增长1.1%","description":"中国2026年第三季度GDP增4.5%，出口36%，零售1.1%。外需驱动为何脆弱，以及对俄罗斯的意义。","blocks":[{"id":"b001","kind":"paragraph","text":"十月19日公布，中国七月至九月GDP较2025年同期增4.5%，分析师预期4.4%。第二季度4.3%，为2022年以来最低；环比增1.2%。前9个月增长4.6%，GDP达107.1万亿元人民币。全年政府目标4.5–5%，数据后看似可实现。"},{"id":"b002","kind":"paragraph","text":"出口贡献最大。九月同比增36.3%，进口31%；单月顺差$133.5十亿，为20个月最大。前9个月芯片出口金额翻倍，电脑与汽车约增54%，九月工业生产增5.5%。"},{"id":"b003","kind":"paragraph","text":"国内却不同。九月零售增1.1%，优于0.5%预期但仍低。前9个月固定资产投资降7.2%，私人投资10.4%，房地产开发20.6%，新房销售面积少13.2%。家庭大部分储蓄在住房里，房价下跌让居民觉得更穷，消费更谨慎。"},{"id":"b004","kind":"paragraph","text":"设想家庭咖啡店向邻城送馅饼，营收涨、厨师忙，本地客却越来越少。邻城继续买则经营良好；一换其他店，增长就停，因为本地客户没扩张。这称外需驱动增长，快却依赖他人决定。欧盟已要求中国减少向其销售高价商品。"},{"id":"b005","kind":"paragraph","text":"俄罗斯关注出口收入。中国是俄燃料最大买家，九月油气煤采购约9.1十亿欧元。工厂满负荷消耗能源，只要出口订单在，原料需求就有支撑。但强数据也降低新增内需刺激概率：既然目标能完成，北京更无须花钱刺激。"},{"id":"b006","kind":"paragraph","text":"EIU高级经济学家徐天辰预计出口及政府投资第四季度仍支撑增长，风险是支点单一。全球AI投资放缓或欧盟壁垒会冲击芯片和汽车销售，本国消费者尚未准备好替代外部。外需保持则工厂忙、俄油采购稳定；外需弱则考验北京多快激活内需。"},{"id":"b007","kind":"heading","text":"中国2026年第三季度GDP增长多少？"},{"id":"b008","kind":"paragraph","text":"较2025年七月至九月增4.5%，预期4.4%；第二季度4.3%，为2022年以来最低。前9个月4.6%，全年目标4.5–5%。"},{"id":"b009","kind":"heading","text":"为何称中国增长失衡？"},{"id":"b010","kind":"paragraph","text":"九月出口增36.3%，零售仅1.1%；前9个月房地产投资跌20.6%。增长依赖海外买家而非本国居民。"},{"id":"b011","kind":"heading","text":"中国加速对俄罗斯意味着什么？"},{"id":"b012","kind":"paragraph","text":"中国是俄油气煤最大买家。工厂被出口订单填满时燃料需求稳定；外需弱化，国内市场暂未准备好补位。"}],"sources":[{"label":"中国第三季度GDP增长4.5%","url":"https://www.interfax.ru/business/1123374"},{"label":"出口激增使中国经济加速","url":"https://www.cnbc.com/2026/10/19/chinas-economic-growth-quickens-to-4point6percent-as-exports-surge-stimulus-rolls-out.html"},{"label":"中国增速回升至4.5%，全年目标更可及","url":"https://www.bloomberg.com/news/articles/2026-10-19/china-s-growth-rebounds-to-4-5-puts-annual-target-within-reach"},{"label":"中国第3季度GDP超预期达4.5%，零售增速为三月以来最快","url":"https://investinglive.com/news/china-q3-gdp-beats-forecasts-at-4-5-retail-sales-grow-at-fastest-pace-since-march/"},{"label":"中国2026年前三季度经济保持稳定","url":"https://www.indexbox.io/blog/chinas-economy-holds-steady-in-first-three-quarters-of-2026-as-trade-and-industry-outpace-broader-growth/"},{"label":"中国九月出口增长36.3%，贸易再平衡压力上升","url":"https://clickondetroit.com/business/2026/10/14/chinas-exports-surge-363-in-september-as-pressure-ramps-up-to-rebalance-trade"},{"label":"中国顺差创20个月最大","url":"https://tradingeconomics.com/china/balance-of-trade/news/591695"},{"label":"2026年九月俄罗斯化石燃料出口与制裁月度分析","url":"https://energyandcleanair.org/september-2026-monthly-analysis-of-russian-fossil-fuel-exports-and-sanctions/"}],"sourceBodySha256":"a43116f5bc45095d81495bfb1beae8eb81d22f98eafffb5342e2297d883572c6"}')}}]);